<?php
require_once dirname(__DIR__).'/src/db.php';
try{require_disposable_test_profile();}catch(Throwable $e){fwrite(STDERR,"REFUSED: ".$e->getMessage()."\n");exit(2);}
$base=rtrim($argv[1]??'','/');if($base===''||!in_array(strtolower((string)parse_url($base,PHP_URL_HOST)),['127.0.0.1','localhost','::1'],true)){fwrite(STDERR,"REFUSED: simulator test requires a loopback scratch server.\n");exit(2);}
$pdo=db();$token=(string)(config()['bridge_tokens']['demo']??config()['bridge_token']??'');$createdZoneId=null;$oldZoneIds=$pdo->query("SELECT id FROM safe_zones WHERE site_id='pup' AND is_active=1")->fetchAll(PDO::FETCH_COLUMN);
function replay_api(string $method,string $path,?array $payload=null,bool $operatorAuth=true):array{
    global $base; $headers="Content-Type: application/json\r\n";
    if($operatorAuth){$headers.="Cookie: ".getenv('TRAILWATCH_TEST_SESSION_COOKIE')."\r\nX-CSRF-Token: ".getenv('TRAILWATCH_TEST_CSRF_TOKEN')."\r\n";}
    $ctx=stream_context_create(['http'=>['method'=>$method,'header'=>$headers,'content'=>$payload===null?'':json_encode($payload,JSON_THROW_ON_ERROR),'ignore_errors'=>true,'timeout'=>8]]);$raw=@file_get_contents($base.$path,false,$ctx);$status=(int)substr($http_response_header[0]??'HTTP/1.1 500',9,3);return ['status'=>$status,'raw'=>is_string($raw)?$raw:'','body'=>is_string($raw)?json_decode($raw,true):null];
}
function replay_expect(int $status,array $result,string $label):array{if($result['status']!==$status)throw new RuntimeException("$label HTTP {$result['status']} {$result['raw']}");echo "PASS $label HTTP $status\n";return is_array($result['body'])?$result['body']:[];}
function replay_check(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);echo "PASS $label\n";}
function replay_run(array $args):array{$cmd=[PHP_BINARY,dirname(__DIR__).'/tools/simulate_hikers.php',...$args];$pipes=[];$proc=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__),getenv());if(!is_resource($proc))throw new RuntimeException('Could not start phase1_replay simulator');fclose($pipes[0]);$out=stream_get_contents($pipes[1]);fclose($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[2]);$status=proc_close($proc);if($status!==0)throw new RuntimeException("phase1_replay failed\n$err$out");return ['out'=>$out,'err'=>$err];}
try{
    $unauth=replay_api('GET','/api/safe-zone',null,false);replay_expect(401,$unauth,'safe-zone bridge read remains token protected');
    replay_expect(200,replay_api('POST','/api/settings/site',['site_id'=>'pup']),'select PUP for simulator replay');
    $session=replay_expect(201,replay_api('POST','/api/test-sessions/start',['label'=>'P4b Phase 1 replay scratch','phase'=>'PHASE1','design'=>'A','tester_code'=>'P4B','test_point'=>'synthetic scratch ring']),'start replay test session');$sessionId=(int)$session['active_session']['id'];
    $centerLat=14.6;$centerLon=121.0;$outerDelta=0.0004;$innerDelta=0.0002;
    $square=static function(float $delta)use($centerLat,$centerLon):array{return [['latitude'=>$centerLat-$delta,'longitude'=>$centerLon-$delta],['latitude'=>$centerLat-$delta,'longitude'=>$centerLon+$delta],['latitude'=>$centerLat+$delta,'longitude'=>$centerLon+$delta],['latitude'=>$centerLat+$delta,'longitude'=>$centerLon-$delta]];};
    $zone=replay_expect(201,replay_api('PUT','/api/safe-zone',['site_id'=>'pup','name'=>'P4b synthetic DEMO ring','rings'=>[$square($outerDelta),$square($innerDelta)]]),'save small two-ring scratch safe zone');$createdZoneId=(int)$zone['safe_zone']['id'];
    $run=replay_run(['--scenario=phase1_replay','--inside-count=3','--outside-count=2','--start-sequence=60000','--base-url='.$base.'/api']);$matches=[];preg_match_all('/Sequence (\d+) \| intended (INSIDE|OUTSIDE) \| classified (INSIDE|OUTSIDE|UNCLASSIFIED)/',$run['out'],$matches,PREG_SET_ORDER);replay_check(count($matches)===5,'replay reports all five accepted sequence/intended/classification results');
    $expected=['INSIDE','INSIDE','INSIDE','OUTSIDE','OUTSIDE'];foreach($matches as $i=>$m)replay_check((int)$m[1]===60000+$i&&$m[2]===$expected[$i]&&$m[3]===$expected[$i],'each replayed point is classified as intended');
    $q=$pdo->prepare("SELECT id FROM test_sessions WHERE site_id='pup' AND ended_at IS NULL ORDER BY id DESC LIMIT 1");$q->execute();replay_check((int)$q->fetchColumn()===$sessionId,'replay packets belong to the active selected-site session');
    $q=$pdo->prepare("SELECT p.sequence_number,p.classification,p.test_mode FROM uplink_packets p JOIN hiker_nodes h ON h.id=p.hiker_node_id WHERE p.site_id='pup' AND p.session_id=? AND h.node_id='H1' AND p.sequence_number BETWEEN 60000 AND 60004 ORDER BY p.sequence_number");$q->execute([$sessionId]);$rows=$q->fetchAll();replay_check(count($rows)===5,'five logical replay packets stored in scratch session');foreach($rows as $i=>$row)replay_check((int)$row['sequence_number']===60000+$i&&$row['classification']===$expected[$i]&&(int)$row['test_mode']===1,'stored classification agrees and packet is flagged test-mode for sequence '.(int)$row['sequence_number']);
    $annotatedRun=replay_run(['--scenario=phase1_replay','--inside-count=2','--outside-count=1','--start-sequence=60100','--annotate','--base-url='.$base.'/api']);replay_check(str_contains($annotatedRun['out'],'H1 sequences 60100-60101 | intended INSIDE | point_source FROM_TRACK')&&str_contains($annotatedRun['out'],'H1 sequences 60102-60102 | intended OUTSIDE | point_source MOVED_BEYOND_MARGIN'),'--annotate prints exact manual sequence ranges when simulator lacks operator login/CSRF');
}catch(Throwable $e){$failure=$e;fwrite(STDERR,'FAIL '.$e->getMessage()."\n");}finally{
    if($createdZoneId!==null){try{$pdo->beginTransaction();$q=$pdo->prepare('DELETE FROM safe_zone_vertices WHERE safe_zone_id=?');$q->execute([$createdZoneId]);$q=$pdo->prepare('DELETE FROM safe_zones WHERE id=?');$q->execute([$createdZoneId]);$pdo->exec("UPDATE safe_zones SET is_active=0 WHERE site_id='pup'");if($oldZoneIds){$marks=implode(',',array_fill(0,count($oldZoneIds),'?'));$q=$pdo->prepare("UPDATE safe_zones SET is_active=1 WHERE id IN ($marks)");$q->execute(array_map('intval',$oldZoneIds));}$pdo->commit();echo "PASS scratch replay restored the original PUP safe-zone active state.\n";}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,"FAIL scratch replay safe-zone cleanup failed: ".$e->getMessage()."\n");exit(1);}}
}
if(isset($failure))exit(1);
